window.B0B_INTRO_CHAPTERS=[{"id": "I", "title": "The record", "year": "2011", "at": 0.0, "end": 16.69, "map": false, "lines": [{"text": "Nuremberg, 1945. The prosecution argued from documents, not rumour."}, {"text": "The record keeps arriving the same way: the Pentagon Papers, the 9/11 Commission, the Senate’s torture report.", "say": "The record keeps arriving the same way. The Pentagon Papers. The nine eleven Commission. The Senate’s torture report."}, {"text": "Show the record. Say where it came from. Let the reader test it."}]}, {"id": "II", "title": "The instrument", "year": "2025", "at": 16.69, "end": 36.08, "map": false, "lines": [{"text": "Washington, 1947. A committee of Congress turned the cameras on citizens."}, {"text": "Now the cameras sit on poles and rooftops, and nobody has to call a hearing."}, {"text": "An inquiry and a hunt look the same from outside. The test: could the finding have come out the other way?"}]}, {"id": "III", "title": "The capability", "year": "2015", "at": 36.08, "end": 54.31, "map": false, "lines": [{"text": "Enewetak, 1952. The capability arrives before the argument about what it is for."}, {"text": "So does the data centre, the drone and the supercomputer."}, {"text": "A document can establish a capability. It does not establish a use. Secrecy is evidence of nothing about what is hidden."}]}, {"id": "IV", "title": "The overhead", "year": "2021", "at": 54.31, "end": 70.23, "map": false, "lines": [{"text": "1958. The first American satellite carried a cosmic-ray counter, not a camera.", "say": "Nineteen fifty-eight. The first American satellite carried a cosmic-ray counter, not a camera."}, {"text": "The cameras came in 1960, as CORONA, and stayed classified for thirty-five years.", "say": "The cameras came in nineteen sixty, as Corona, and stayed classified for thirty-five years."}, {"text": "Now the night side of the planet is a public photograph."}]}, {"id": "V", "title": "The annotation", "year": "2003", "at": 70.23, "end": 88.07, "map": false, "lines": [{"text": "October 1962. A reconnaissance photograph became evidence when somebody labelled it, and the missiles were there."}, {"text": "February 2003, the same Council: labelled slides again. This time the weapons were not."}, {"text": "The label is the claim. Check it, including every caption in this film."}]}, {"id": "VI", "title": "The public", "year": "2020", "at": 88.07, "end": 105.54, "map": false, "lines": [{"text": "1963. 1967. 2003. 2011. 2020. The placards change; the shape of the crowd does not.", "say": "Nineteen sixty-three. Sixty-seven. Two thousand and three. Twenty eleven. Twenty twenty. The placards change; the shape of the crowd does not."}, {"text": "A crowd is testimony: evidence of an experience, never, by itself, evidence of a cause."}, {"text": "The newsreel filmed the counter-demonstrators too."}]}, {"id": "VII", "title": "The inquiry", "year": "2012", "at": 105.54, "end": 121.37, "map": false, "lines": [{"text": "The transcripts, 1974. The Church Committee, 1975. Iran-Contra, 1987.", "say": "The transcripts, nineteen seventy-four. The Church Committee, seventy-five. Iran-Contra, eighty-seven."}, {"text": "The inquiry always comes afterwards."}, {"text": "Everything in this report arrived the same way: late, in public, and on the record."}]}, {"id": "VIII", "title": "The ledger", "year": "2026", "at": 121.37, "end": null, "map": true, "lines": [{"text": "{TOTAL} documented sites. Twenty-five sections.", "say": "{TOTALWORDS} documented sites. Twenty-five sections."}, {"text": "Every source named. Every tier stated."}, {"text": "The specimens it could not prove, killed on its own page."}, {"text": "The authority of a document does not come from what it alleges."}, {"text": "It comes from what it refuses to allege."}, {"text": "τετέλεσται — it has been completed, and remains so.", "say": "Teh-teh-less-tie. It has been completed, and it remains so."}]}];
window.B0B_INTRO_REEL_DUR=121.37;
